#!/usr/bin/env bash
# Write a VM's /var/lib/secrets/* from .env: ./scripts/push-secrets.sh <host> [--check]
#
# Which files a host gets comes from its settings.json (`secrets`, generated by
# tofu); how each is built from .env is in scripts/lib/secrets.sh. Use this after
# rotating a secret in .env, or after adding one to a VM that's already installed.
#
#   --check   compare the VM's files with .env without changing anything
#
# Needs: `set -a; source .env; set +a` in this shell, and SSH as root to the VM.
set -euo pipefail

host=${1:?usage: $0 <host> [--check]}
mode=${2:-push}
root=$(cd "$(dirname "$0")/.." && pwd)
settings="$root/nixos/hosts/$host/settings.json"
source "$root/scripts/lib/secrets.sh"

[[ -f "$settings" ]] || { echo "no $settings - is '$host' in nixos_vms and applied?" >&2; exit 1; }
ip=$(jq -r .ipv4_address "$settings")
mapfile -t names < <(jq -r '.secrets // [] | .[]' "$settings")
(( ${#names[@]} )) || { echo "$host: no secrets configured"; exit 0; }

# Render locally into a private tmpfs dir, removed on exit.
staging=$(mktemp -d "${XDG_RUNTIME_DIR:-/tmp}/push-secrets.XXXXXX")
trap 'rm -rf "$staging"' EXIT
render_secrets "$staging" "${names[@]}"

ssh_opts=(-o BatchMode=yes -o ConnectTimeout=10)

if [[ $mode == --check ]]; then
  remote=$(ssh "${ssh_opts[@]}" "root@$ip" \
    "cd /var/lib/secrets 2>/dev/null && sha256sum ${names[*]} 2>/dev/null" || true)
  rc=0
  for n in "${names[@]}"; do
    want=$(sha256sum < "$staging/$n" | cut -d' ' -f1)
    have=$(awk -v f="$n" '$2 == f { print $1 }' <<< "$remote")
    if [[ -z $have ]]; then echo "$host: $n MISSING"; rc=1
    elif [[ $have == "$want" ]]; then echo "$host: $n ok"
    else echo "$host: $n DIFFERS from .env"; rc=1; fi
  done
  exit $rc
fi

# Only the files themselves are sent; /var/lib/secrets stays root-only.
tar -C "$staging" -cf - "${names[@]}" | ssh "${ssh_opts[@]}" "root@$ip" '
  set -e
  install -d -m 0700 -o root -g root /var/lib/secrets
  tar -C /var/lib/secrets -xf - --no-same-owner --no-overwrite-dir
  chmod 0600 /var/lib/secrets/*'
echo "$host: wrote ${names[*]}"

# Services that only read their secret at start.
for n in "${names[@]}"; do
  case "$n" in
    cloudflared-token)
      ssh "${ssh_opts[@]}" "root@$ip" 'systemctl restart cloudflared-token-secret.service' \
        && echo "$host: restarted cloudflared-token-secret" ;;
  esac
done
